\appendix



\section{Dark matter-nucleon coupling}\label{app:dm-nucleon}
The dimensionful coupling between the mass eigenstates $(h,\,H)$ and pNG DM $\chi$ arises from eq.~\eqref{eqn:S_part}, namely
\begin{equation}\label{eqn:DM-h1-h2}
	\lagr_S \supset - \left(\lambda_{\Phi S}\, \Phi^\dagger \Phi |S|^2 + \frac{\lambda_S}{2} |S|^4 \right).
\end{equation}
After EWSB, this term expands to (keeping only terms proportional to $\phi \chi^2$ and $s \chi^2$)
\begin{align*}
	\lambda_{\Phi S} \, \Phi^\dagger \Phi |S|^2 &= \frac{\lambda_{\Phi S}}{4} (v_h + \phi)^2 \left[(v_s + s)^2 + \chi^2 \right] \supset \frac{\lambda_{\Phi S}}{4} (2 v_h \phi) \chi^2 = \frac{\lambda_{\Phi S} v_h}{2} \phi \chi^2, \\[1.5mm]
	\frac{\lambda_S}{2} |S|^4 &= \frac{\lambda_S}{8} \left[ (v_s + s)^2 + \chi^2 \right]^2 \supset \frac{\lambda_S}{8} \left[2 (v_s + s)^2 \chi^2 \right] \supset \frac{\lambda_S}{8} (4 v_s s) \chi^2 = \frac{\lambda_S v_s}{2} s \chi^2.
\end{align*}
Thus, eq.~\eqref{eqn:DM-h1-h2} can be expressed as
\begin{equation}\label{eqn:DM-h-s}
	\lagr_S \supset - \frac{1}{2} \chi^2 \left( \lambda_{\Phi S}  v_h \,\phi + \lambda_S v_s \,s \right).
\end{equation}
Using the following relation for the interaction eigenstates:
\begin{equation}
	\begin{pmatrix}
		\phi \\
		s 
	\end{pmatrix} = 
	\begin{pmatrix}
		\cos\theta & \sin\theta \\
		-\sin\theta & \cos\theta
	\end{pmatrix}
	\begin{pmatrix}
		h \\
		H
	\end{pmatrix},
\end{equation}
we can rewrite eq.~\eqref{eqn:DM-h-s} as
\begin{equation}\label{eqn:temp_DM_nucleon}
	\lagr_S \supset - \frac{1}{2} \chi^2 (\kappa_{\chi \chi h} \, h + \kappa_{\chi \chi H} \, H),
\end{equation} 
where the \emph{dimensionful} couplings $\{\kappa_{\chi \chi h},\,\kappa_{\chi \chi H}\}$ are \cite{Gross:2017dan}
{\small
    \begin{align}
	    \kappa_{\chi \chi h} = \left(\lambda_{\Phi S} v_h \cos\theta - \lambda_S v_s \sin\theta \right) &= \frac{1}{v_s} \left[ (m_H^2 - m_h^2) \sin \theta \cos^2 \theta - \sin\theta (m_h^2 \sin^2 \theta + m_H^2 \cos^2 \theta) \right] \nonumber \\
	    &= - \frac{m_h^2}{v_s} \sin\theta, \\[1.5mm]
	    \kappa_{\chi \chi H} = \left(\lambda_{\Phi S} v_h \sin\theta + \lambda_S v_s \cos\theta \right) &= \frac{1}{v_s} \left[(m_H^2 - m_h^2) \sin^2 \theta \cos \theta + \cos\theta (m_h^2 \sin^2 \theta + m_H^2 \cos^2 \theta) \right] \nonumber \\
	    &= + \frac{m_H^2}{v_s} \cos\theta.
    \end{align}
}
On the other hand, the Yukawa interaction term in the SM Lagrangian reads
\begin{equation}
	\lagr_{\textrm{Yukawa}} \supset - \phi \sum_f \frac{m_f}{v_h} \ovr{f} f = - \sum_f \kappa_{h f\ovr{f}} \, h \ovr{f} f + \kappa_{H f\ovr{f}} \, H \ovr{f} f,
\end{equation}
where 
\begin{equation}
	\kappa_{h f\ovr{f}} = \frac{m_f}{v_h} \cos\theta, \quad \kappa_{H f\ovr{f}} = \frac{m_f}{v_h} \sin \theta,
\end{equation}
are the \emph{dimensionless} couplings between $h/H$ and SM quarks/leptons.~Finally, the pNG DM-nucleon interaction Lagrangian can be written as
\begin{equation}
	\lagr_{\chi f} \supset - \frac{1}{2} \chi^2 (\kappa_{\chi \chi h} \, h + \kappa_{\chi \chi H} \, H) - \sum_f \kappa_{h f\ovr{f}} \, h \ovr{f} f + \kappa_{H f\ovr{f}} \, H \ovr{f} f.
\end{equation}

For a $\chi f \rightarrow \chi f$ scattering process via an $h/H$ exchange in $t$-channel, the tree-level direct detection (DD) scattering amplitude is proportional to
\begin{align*}
	\mathcal{A}_{\textrm{DD}}(q^2) \propto \frac{\kappa_{\chi \chi h} \kappa_{h f\ovr{f}}}{q^2 - m_h^2} + \frac{\kappa_{\chi \chi H} \kappa_{H f\ovr{f}}}{q^2 - m_H^2} \propto \sin\theta \cos\theta \left(\frac{m_H^2}{q^2 - m_H^2} - \frac{m_h^2}{q^2 - m_h^2}\right),
\end{align*}
where $q \equiv \sqrt{2 M E}$ is the momentum transfer and $M$ is the nucleus mass.~In the limit of $q^2 \ll m_{h,H}^2$, the above expression becomes
\begin{equation}
	\mathcal{A}_{\textrm{DD}}(q^2) \propto \sin\theta \cos\theta \left(\frac{1}{1 - q^2/m_h^2} - \frac{1}{1 - q^2/m_H^2}\right).
\end{equation}
For $x \ll 1$, the Taylor expansion for $(1 - x)^{-1} = 1 + x + \mathcal{O}(x^2)$. Thus, the above expression expands to
\begin{equation}
	\mathcal{A}_{\textrm{DD}}(q^2) \propto q^2 \sin\theta \cos\theta \left(\frac{1}{m_h^2} - \frac{1}{m_H^2}\right).
\end{equation}
As $q \sim \mathcal{O}(10)$\,MeV, the pNG DM-nucleon cross section is momentum-suppressed at tree-level.



\section{The $S$, $T$ and $U$ parameters}\label{app:oblique_pars}
In our model, the oblique parameters are shifted from their SM values by \cite{Grimus:2008nb,Beniwal:2018hyi}
\begin{align}
    \Delta T &= \frac{3}{16\pi s_W^2} \left[\cos^2\theta \left \{f_T    \left(\frac{m_h^2}{m_W^2}\right) - \frac{1}{c_W^2}f_T\left(\frac{m_h^2}{m_Z^2}\right) \right\} + \sin^2\theta \left\{f_T\left(\frac{m_H^2}{m_W^2} \right) \right. \right. \nonumber \\
    &\hspace{4mm} \left. \left. - \frac{1}{c_W^2} f_T\left(\frac{m_H^2}{m_Z^2} \right) \right\} - \left\{f_T\left(\frac{m_h^2}{m_W^2}\right) - \frac{1}{c_W^2}f_T\left(\frac{m_h^2}{m_Z^2}\right) \right\} \right], \label{eqn:del_T} \\[1.5mm]
    \Delta S &= \frac{1}{2\pi} \left[\cos^2\theta f_S \left(\frac{m_h^2}{m_Z^2}\right) + \sin^2\theta f_S \left(\frac{m_H^2}{m_Z^2}\right) - f_S \left(\frac{m_h^2}{m_Z^2}\right) \right], \label{eqn:del_S} \\[1.5mm]    
    \Delta U &= \frac{1}{2\pi} \left[\cos^2\theta f_S \left(\frac{m_h^2}{m_W^2}\right) + \sin^2\theta f_S \left(\frac{m_H^2}{m_W^2}\right) - f_S \left(\frac{m_h^2}{m_W^2}\right) \right] - \Delta S, \label{eqn:del_U}
\end{align}
where $\Delta \mathcal{O} \equiv \mathcal{O} - \mathcal{O}_{\textnormal{SM}}$ for $\mathcal{O} \in (S, T, U)$, $m_W\,(m_Z)$ is the $W\,(Z)$ boson mass, $c_W^2 = m_W^2/m_Z^2$ and $s_W^2 = 1 - c_W^2$. The loop functions $f_T(x)$ and $f_S(x)$ are given by
\begin{align}
    f_T(x) &= \frac{x\log x}{x-1}, \\[1.5mm]
    f_S(x) &= 
    \begin{dcases}
        \frac{1}{12} \left[ -2 x^2 + 9 x + \left((x-3) \left(x^2-4 x+12\right)+\frac{1-x}{x}\right) f_T(x) \right. \\ 
        \left. + 2 \sqrt{(4-x) x} \left(x^2-4 x+12\right)    
        \tan ^{-1}\left(\sqrt{\frac{4 - x}{x}}\right) \right], \quad 0 < x < 4, \\
        \frac{1}{12} \left[-2 x^2 + 9 x + \left((x-3) \left(x^2-4 x+12\right)+\frac{1-x}{x}\right)f_T(x) \right. \\
        \left. + \sqrt{(x-4) x} \left(x^2 - 4x + 12\right)  \log \left( \frac{x - \sqrt{(x-4)x}}{x + \sqrt{(x-4)x}} \right)\right], \quad x \geq 4. 
    \end{dcases} 
\end{align} 


