(*--------------------------------------------------------------------*)
(* Model: pNG_gen                                              *)
(* Generated by HEPTAPOD GenerateFeynRulesModelTool.                    *)
(*--------------------------------------------------------------------*)

M$ModelName = "pNG_gen";

M$Information = {
  Authors -> {"Chiara Arina", "Ankit Beniwal", "Celine Degrande", "Jan Heisig", "Andre Scaffidi"},
  Version -> "1.0.0",
  Date -> "2025-09-25",
  Institutions -> {"UCLouvain", "University of Adelaide"},
  Emails -> {"chiara.arina@uclouvain.be", "ankit.beniwal@uclouvain.be", "celine.degrande@uclouvain.be", "jan.heisig@uclouvain.be", "andre.scaffidi@adelaide.edu.au"}
};

M$InteractionOrderHierarchy = {{QCD, 1}, {QED, 2}, {NP, 1}};

M$InteractionOrderLimit = {{QCD, 99}, {QED, 99}, {NP, 99}};

FeynmanGauge = True;

M$vevs = {{Phi[2], vev}};

M$Parameters = {
  vs == {
    ParameterType -> External,
    Value -> 1000.,
    BlockName -> PNG,
    OrderBlock -> 2,
    InteractionOrder -> {NP, 1},
    Description -> "Singlet VEV v_s [GeV]"
  },
  theta == {
    ParameterType -> External,
    Value -> 0.1,
    BlockName -> PNG,
    OrderBlock -> 3,
    InteractionOrder -> {NP, 1},
    Description -> "Higgs mixing angle [rad]"
  },
  lambdaPhi == {
    ParameterType -> Internal,
    Value -> (MH^2*Cos[theta]^2 + mH^2*Sin[theta]^2)/vev^2,
    InteractionOrder -> {QED, 2},
    Description -> "Higgs quartic coupling lambda_Phi"
  },
  lambdaS == {
    ParameterType -> Internal,
    Value -> (MH^2*Sin[theta]^2 + mH^2*Cos[theta]^2)/vs^2,
    InteractionOrder -> {NP, 1},
    Description -> "Singlet quartic coupling lambda_S"
  },
  lambdaPhiS == {
    ParameterType -> Internal,
    Value -> (mH^2 - MH^2)*Sin[theta]*Cos[theta]/(vev*vs),
    InteractionOrder -> {NP, 1},
    Description -> "Portal coupling lambda_PhiS"
  },
  muSprime2 == {
    ParameterType -> Internal,
    Value -> m_chi^2,
    Description -> "Soft breaking parameter mu_S'^2"
  },
  muPhi2 == {
    ParameterType -> Internal,
    Value -> lambdaPhi*vev^2 + lambdaPhiS*vs^2,
    Description -> "Higgs quadratic parameter mu_Phi^2"
  },
  muS2 == {
    ParameterType -> Internal,
    Value -> lambdaS*vs^2 + lambdaPhiS*vev^2 - muSprime2,
    Description -> "Singlet quadratic parameter mu_S^2"
  }
};

M$ClassesDescription = {
  S[100] == {
    ClassName -> S,
    SelfConjugate -> False,
    Unphysical -> True,
    Definitions -> {S -> (vs + (-Sin[theta]*H + Cos[theta]*HH) + I*chi)/Sqrt[2], Sbar -> (vs + (-Sin[theta]*H + Cos[theta]*HH) - I*chi)/Sqrt[2]}
  },
  S[101] == {
    ClassName -> HH,
    SelfConjugate -> True,
    Mass -> {mH, 200.},
    Width -> {WHH, 1.},
    PDG -> 9900025,
    ParticleName -> "HH",
    AntiParticleName -> "HH",
    FullName -> "Heavy Higgs",
    PropagatorLabel -> "HH",
    PropagatorType -> D,
    PropagatorArrow -> None
  },
  S[102] == {
    ClassName -> chi,
    SelfConjugate -> True,
    Mass -> {m_chi, 100.},
    Width -> {Wchi, 1.},
    PDG -> 9900055,
    ParticleName -> "chi",
    AntiParticleName -> "chi",
    FullName -> "pNG DM",
    PropagatorLabel -> "chi",
    PropagatorType -> D,
    PropagatorArrow -> None
  }
};

LHiggsTotal = DC[Phibar[ii], mu] DC[Phi[ii], mu] + DC[Sbar, mu] DC[S, mu] - muPhi2/2 Phibar[ii] Phi[ii] + lambdaPhi/2 (Phibar[ii] Phi[ii])^2 - lambdaPhiS Phibar[ii] Phi[ii] Sbar S - lambdaS/2 (Sbar S)^2 + muSprime2/4 (S^2 + Sbar^2);

LTotal = LGauge + LFermions + LHiggsTotal + LYukawa + LGhost;

